const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let items=[],current=null,view='all',sortMode='recent',objectUrls=[],libraries=[],progress={},playQueue=[],history=[],subscriptions=[],playlists=[],reminders=[],bookmarks=[],lastSession=null,repeatMode='off',shuffleOn=false,selected=new Set(),selectMode=false,appearance='dark',density='comfortable',autoAdvance=true,confirmDelete=true,reducedMotion=false,highContrast=false,largeText=false,focusMode=false,audioMode=false,detailRating=0,activePlaylist=null,pendingImport=null,saveTimer=null,lastProgressSave=0;
const mediaExt=/\.(mp4|webm|ogv|mov|m4v|mkv|avi|mp3|m4a|aac|wav|ogg|oga|opus|flac|jpg|jpeg|png|gif|webp|avif|bmp|svg)$/i;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2300)}
function kindOf(f){if(f.type.startsWith('video/'))return'video';if(f.type.startsWith('audio/'))return'audio';if(f.type.startsWith('image/'))return'image';return /\.(mp3|m4a|aac|wav|ogg|oga|opus|flac)$/i.test(f.name)?'audio':/\.(jpg|jpeg|png|gif|webp|avif|bmp|svg)$/i.test(f.name)?'image':'video'}
function normalize(x){return {id:x.id||crypto.randomUUID(),name:x.title||x.name||'Untitled',type:x.type||'video',url:x.url||'',embed:x.embedUrl||x.embed||'',sourceUrl:x.sourceUrl||x.url||'',thumbnail:x.thumbnail||'',source:x.provider||x.source||'Local file',description:x.description||'',duration:x.duration,publishedAt:x.publishedAt,added:x.added||Date.now(),favorite:!!x.favorite,library:x.library||'',watchLater:!!x.watchLater,rating:Number(x.rating)||0,notes:x.notes||'',tags:Array.isArray(x.tags)?x.tags:[]}}
function merge(fresh){let known=new Set(items.map(x=>x.id));let added=fresh.map(normalize).filter(x=>!known.has(x.id));items=[...added,...items];scheduleStateSave();return added.length}
function scheduleStateSave(){clearTimeout(saveTimer);saveTimer=setTimeout(saveState,450)}
let volumeLevel=1;
async function saveState(){let webItems=items.filter(x=>x.source!=='Local file');try{await fetch('/api/state',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({libraries,items:webItems,queue:playQueue.filter(id=>webItems.some(x=>x.id===id)),history:history.slice(0,100),preferences:{repeatMode,shuffleOn,appearance,density,autoAdvance,confirmDelete,reducedMotion,highContrast,largeText,subscriptions,playlists,reminders,bookmarks,lastSession,volume:volumeLevel,speed:Number($('#speedSelect').value||1)},replaceItems:true,replaceLibraries:true})})}catch{}}
async function loadState(){try{let d=await (await fetch('/api/state')).json();libraries=Array.isArray(d.libraries)?d.libraries:[];progress=d.progress||{};history=Array.isArray(d.history)?d.history:[];repeatMode=d.preferences?.repeatMode||'off';shuffleOn=!!d.preferences?.shuffleOn;appearance=d.preferences?.appearance||'dark';density=d.preferences?.density||'comfortable';autoAdvance=d.preferences?.autoAdvance!==false;confirmDelete=d.preferences?.confirmDelete!==false;volumeLevel=Math.min(1,Math.max(0,Number(d.preferences?.volume??1)));['video','audio'].forEach(id=>{$('#'+id).volume=volumeLevel});$('#speedSelect').value=String(d.preferences?.speed||1);subscriptions=Array.isArray(d.preferences?.subscriptions)?d.preferences.subscriptions:[];playlists=Array.isArray(d.preferences?.playlists)?d.preferences.playlists:[];reminders=Array.isArray(d.preferences?.reminders)?d.preferences.reminders:[];bookmarks=Array.isArray(d.preferences?.bookmarks)?d.preferences.bookmarks:[];lastSession=d.preferences?.lastSession||null;reducedMotion=!!d.preferences?.reducedMotion;highContrast=!!d.preferences?.highContrast;largeText=!!d.preferences?.largeText;merge(d.items||[]);playQueue=(d.queue||[]).filter(id=>items.some(x=>x.id===id));applyPreferences();updateControlLabels();render();renderRecovery()}catch{libraries=JSON.parse(localStorage.getItem('om_libraries')||'[]');render()}}
function addFiles(fs){let valid=[...fs].filter(f=>f.type.match(/^(video|audio|image)\//)||mediaExt.test(f.name));valid.forEach(f=>{let url=URL.createObjectURL(f);objectUrls.push(url);items.unshift(normalize({name:f.name,type:kindOf(f),url,source:'Local file'}))});render();if(valid[0])play(items[valid.length-1]);toast(`${valid.length} item${valid.length!==1?'s':''} added`)}
function parseWeb(url){try{let u=new URL(url),h=u.hostname.replace('www.',''),id;if(h.includes('youtube.com')){id=u.searchParams.get('v')||u.pathname.split('/').filter(Boolean).pop();return normalize({id:'YouTube:video:'+id,name:'YouTube media',source:'YouTube',sourceUrl:url,embed:`https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}?autoplay=1`})}if(h==='youtu.be'){id=u.pathname.slice(1);return normalize({id:'YouTube:video:'+id,name:'YouTube media',source:'YouTube',sourceUrl:url,embed:`https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}?autoplay=1`})}if(h.includes('dailymotion.com')||h==='dai.ly'){id=h==='dai.ly'?u.pathname.slice(1):u.pathname.match(/video\/([^_/?]+)/)?.[1];return normalize({id:'Dailymotion:video:'+id,name:'Dailymotion media',source:'Dailymotion',sourceUrl:url,embed:`https://www.dailymotion.com/embed/video/${id}?autoplay=1`})}if(h.includes('vimeo.com')){id=u.pathname.match(/(\d+)/)?.[1];return normalize({id:'Vimeo:video:'+id,name:'Vimeo media',source:'Vimeo',sourceUrl:url,embed:`https://player.vimeo.com/video/${id}?autoplay=1`})}if(h.includes('soundcloud.com'))return normalize({id:'SoundCloud:audio:'+url,name:'SoundCloud media',type:'audio',source:'SoundCloud',sourceUrl:url,embed:`https://w.soundcloud.com/player/?url=${encodeURIComponent(url)}&auto_play=true`});
const host=h;
if(host.includes('twitch.tv')){let m;if(m=host.includes('clips.twitch.tv')?u.pathname.slice(1).split('/')[0]:u.pathname.match(/\/videos\/(\d+)/)){let kind=host.includes('clips.twitch.tv')?'clip=':'video=';if(Array.isArray(m))kind='video=';let id=Array.isArray(m)?m[1]:m;return normalize({id:'Twitch:video:'+id,name:'Twitch media',source:'Twitch',sourceUrl:url,embed:`https://player.twitch.tv/?${kind}${id}&parent=${location.hostname}&autoplay=true`})}let ch=u.pathname.split('/').filter(Boolean)[0];if(ch&&!['videos','directory','search'].includes(ch))return normalize({id:'Twitch:live:'+ch,name:ch+' on Twitch',source:'Twitch',sourceUrl:url,embed:`https://player.twitch.tv/?channel=${encodeURIComponent(ch)}&parent=${location.hostname}&autoplay=true`});return null}
if(host.includes('tiktok.com')){let id=u.pathname.match(/video\/(\d+)/)?.[1];if(id)return normalize({id:'TikTok:video:'+id,name:'TikTok video',source:'TikTok',sourceUrl:url,embed:`https://www.tiktok.com/embed/v2/${id}`});return null}
if(host.includes('reddit.com')||host==='redd.it'){let id=u.pathname.match(/comments\/([a-z0-9]+)/i)?.[1]||u.pathname.split('/').filter(Boolean).pop();return normalize({id:'Reddit:video:'+id,name:'Reddit post',source:'Reddit',sourceUrl:url,embed:`https://www.reddit.com/comments/${id}/?embed=true`})}
if(host.includes('bilibili.com')){let bv=u.pathname.match(/(BV[0-9A-Za-z]+)/)?.[1];let av=u.pathname.match(/av(\d+)/i)?.[1];return normalize({id:'Bilibili:video:'+(bv||av),name:'Bilibili video',source:'Bilibili',sourceUrl:url,embed:bv?`https://player.bilibili.com/player.html?bvid=${bv}&autoplay=1`:`https://player.bilibili.com/player.html?aid=${av}&autoplay=1`})}
if(host.includes('odysee.com')){let p=u.pathname.replace(/^\/\$\/(embed\/)?/,'').replace(/^\//,'');if(p)return normalize({id:'Odysee:video:'+p,name:'Odysee video',source:'Odysee',sourceUrl:url,embed:`https://odysee.com/$/embed/${p}`});return null}
if(host.includes('archive.org')){let id=u.pathname.match(/(?:details|embed|download)\/([^/?#]+)/)?.[1];if(id)return normalize({id:'Internet Archive:video:'+id,name:'Internet Archive item',source:'Internet Archive',sourceUrl:url,embed:`https://archive.org/embed/${id}`});return null}
if(host.includes('nicovideo.jp')){let id=u.pathname.match(/(sm\d+|nm\d+|so\d+)/)?.[1];if(id)return normalize({id:'Niconico:video:'+id,name:'Niconico video',source:'Niconico',sourceUrl:url,embed:`https://embed.nicovideo.jp/watch/${id}`});return null}
if(host.includes('kick.com')){let ch=u.pathname.split('/').filter(Boolean)[0];if(ch&&!['video','videos','category'].includes(ch))return normalize({id:'Kick:live:'+ch,name:ch+' on Kick',source:'Kick',sourceUrl:url,embed:`https://player.kick.com/${encodeURIComponent(ch)}?autoplay=true`});return null}
if(host.includes('x.com')||host.includes('twitter.com')){if(/\/status\/\d+/.test(u.pathname))return normalize({id:'X:post:'+u.pathname.split('/').pop(),name:'Post on X',source:'X (Twitter)',sourceUrl:url,embed:`https://twitframe.com/show?url=${encodeURIComponent(url)}`});return null}
if(host.includes('instagram.com')){let sc=u.pathname.match(/\/(?:p|reel|reels)\/([A-Za-z0-9_-]+)/)?.[1];if(sc)return normalize({id:'Instagram:post:'+sc,name:'Instagram post',source:'Instagram',sourceUrl:url,embed:`https://www.instagram.com/p/${sc}/embed`});return null}if(mediaExt.test(u.pathname))return normalize({id:'url:'+url,name:u.pathname.split('/').pop(),type:/\.(jpg|jpeg|png|gif|webp|avif|bmp|svg)$/i.test(u.pathname)?'image':/\.(mp3|m4a|aac|wav|ogg|oga|opus|flac)$/i.test(u.pathname)?'audio':'video',url,source:'Direct URL',sourceUrl:url});return null}catch{return null}}
function addUrl(url){let x=parseWeb(url);if(!x)return toast('Unsupported media link');if(!items.some(i=>i.id===x.id))items.unshift(x);render();play(x)}
function updateNowBar(x){if(!x)return;$('#nowTitle').textContent=x.name;$('#nowMeta').textContent=x.source+' · '+x.type;$('#favBtn').textContent=x.favorite?'♥':'♡';$('#sourceLink').hidden=!x.sourceUrl;$('#favBtn').classList.toggle('active',x.favorite);$('#watchLaterBtn').classList.toggle('active',x.watchLater);$('#watchLaterBtn').textContent=x.watchLater?'◷✓':'◷';$('#detailsBtn').classList.toggle('active',x.rating>0||!!x.notes)}
function play(x){if(x.type==='playlist')return expandPlaylist(x);if(x.type==='channel'){window.open(x.sourceUrl,'_blank','noopener');return}current=x;lastSession={itemId:x.id,playedAt:Date.now()};if(!playQueue.includes(x.id))playQueue.push(x.id);history=[{id:x.id,playedAt:Date.now()},...history.filter(h=>h.id!==x.id)].slice(0,100);scheduleStateSave();$('#emptyState').hidden=true;$('#viewer').hidden=false;$('#nowbar').hidden=false;['video','audio','image','embed'].forEach(id=>{let e=$('#'+id);e.style.display='none';if(e.pause)e.pause()});if(x.embed){$('#embed').src=x.embed;$('#embed').style.display='block';$('#speedSelect').disabled=true;$('#muteBtn').disabled=true}else{let e=$('#'+x.type);e.src=x.url;e.style.display='block';if(x.type!=='image'){e.playbackRate=Number($('#speedSelect').value);let saved=progress[x.id];e.onloadedmetadata=()=>{if(saved?.position>5&&saved.position<e.duration-10)e.currentTime=saved.position};e.play().catch(()=>{});$('#speedSelect').disabled=false;$('#muteBtn').disabled=false}}updateNowBar(x);$('#sourceLink').href=x.sourceUrl||'#';renderQueue()}
async function expandPlaylist(x){let id=x.id.split(':').pop();toast('Loading playlist…');try{let r=await fetch('/api/playlist?id='+encodeURIComponent(id)),d=await r.json();if(!r.ok)throw Error(d.error);let n=merge(d.results||[]);render();if(d.results?.[0])play(items.find(i=>i.id===normalize(d.results[0]).id));toast(`${n} playlist videos added${d.cacheHit?' · cached':''}`)}catch(e){toast(e.message||'Playlist failed')}}
function filtered(){let q=$('#search').value.trim().toLowerCase();return items.filter(x=>(view==='all'||view===x.type||(view==='favorite'&&x.favorite)||(view==='watchlater'&&x.watchLater)||(view==='rated'&&x.rating>0)||(view==='continue'&&progress[x.id]?.position>5&&progress[x.id].duration-progress[x.id].position>10)||(view==='history'&&history.some(h=>h.id===x.id))||(view==='recent'&&history.some(h=>h.id===x.id&&Date.now()-h.playedAt<604800000))||(view.startsWith('provider:')&&x.source.toLowerCase()===view.slice(9).toLowerCase())||(view.startsWith('lib:')&&x.library===view.slice(4)))&&(x.name+' '+x.source+' '+(x.description||'')+' '+(x.tags||[]).join(' ')).toLowerCase().includes(q)).sort((a,b)=>view==='continue'?(progress[b.id]?.updated||0)-(progress[a.id]?.updated||0):(view==='history'||view==='recent')?(history.findIndex(h=>h.id===a.id)-history.findIndex(h=>h.id===b.id)):sortMode==='oldest'?a.added-b.added:sortMode==='rating'?b.rating-a.rating:sortMode==='az'?a.name.localeCompare(b.name):b.added-a.added)}
function typeIcon(x){return x.type==='video'?'▶':x.type==='audio'?'♪':x.type==='image'?'▧':x.type==='playlist'?'☷':'◉'}
function render(){let arr=filtered();$('#mediaGrid').innerHTML=arr.map(x=>`<article class="media-card ${selected.has(x.id)?'selected':''}" data-id="${esc(x.id)}"><button class="card-select" data-select="${esc(x.id)}" ${selectMode?'':'hidden'}>${selected.has(x.id)?'✓':''}</button><div class="thumb">${x.thumbnail||x.type==='image'?`<img src="${esc(x.thumbnail||x.url)}" alt="">`:`<span class="type-icon">${typeIcon(x)}</span>`}<span class="duration">${esc(x.source)}</span></div><div class="card-body"><b title="${esc(x.name)}">${esc(x.name)}</b><small>${esc(x.type)}${x.rating?' · '+'★'.repeat(x.rating):''}${x.watchLater?' · Watch later':''}${x.tags?.length?' · #'+x.tags.slice(0,2).join(' #'):''}${x.duration?' · '+Math.round(x.duration/60)+' min':''}${x.type==='playlist'?' · click to browse':''}</small></div></article>`).join('')||'<p class="muted">No media in this view yet.</p>';$$('.media-card').forEach(c=>c.onclick=e=>{if(selectMode){if(!e.target.dataset.select)toggleSelection(c.dataset.id)}else play(items.find(x=>x.id===c.dataset.id))});$$('[data-select]').forEach(b=>b.onclick=e=>{e.stopPropagation();toggleSelection(b.dataset.select)});updateBatchBar();$('#allCount').textContent=items.length;$('#summary').textContent=`${arr.length} item${arr.length!==1?'s':''}`;renderQueue();renderLibraries()}
function renderQueue(){playQueue=playQueue.filter(id=>items.some(x=>x.id===id));let q=playQueue.map(id=>items.find(x=>x.id===id)).filter(Boolean);$('#queueCount').textContent=`${q.length} item${q.length!==1?'s':''}`;$('#queueList').innerHTML=q.map((x,i)=>`<div class="queue-item ${current?.id===x.id?'playing':''}" data-id="${esc(x.id)}"><span class="queue-index">${current?.id===x.id?'▶':i+1}</span><div><b>${esc(x.name)}</b><small>${esc(x.source)}</small></div><button class="queue-remove" data-remove="${esc(x.id)}" title="Remove">×</button></div>`).join('')||'<p class="muted">Queue is empty.</p>';$$('.queue-item').forEach(c=>c.onclick=e=>{if(!e.target.dataset.remove)play(items.find(x=>x.id===c.dataset.id))});$$('[data-remove]').forEach(b=>b.onclick=e=>{e.stopPropagation();playQueue=playQueue.filter(id=>id!==b.dataset.remove);scheduleStateSave();renderQueue()})}
function renderLibraries(){renderPlaylists();renderSubscriptions();let providers=[...new Set(items.map(x=>x.source).filter(x=>x&&x!=='Local file'))].sort();$('#smartList').innerHTML=providers.map(name=>`<button class="smart-btn" data-provider="${esc(name)}"><span>◈</span>${esc(name)}<em>${items.filter(x=>x.source===name).length}</em></button>`).join('')||'<small class="muted">Provider collections appear automatically.</small>';$$('.smart-btn').forEach(b=>b.onclick=()=>{view='provider:'+b.dataset.provider;$('#viewTitle').textContent=b.dataset.provider;render()});$('#libraryList').innerHTML=libraries.map(l=>`<button class="library-btn" data-name="${esc(l)}">▤ ${esc(l)}</button>`).join('');$$('.library-btn').forEach(b=>b.onclick=()=>{view='lib:'+b.dataset.name;$('#viewTitle').textContent=b.dataset.name;render()})}
$('#discoverForm').onsubmit=async e=>{e.preventDefault();let b=e.submitter;b.disabled=true;b.textContent='Searching…';$('#warnings').textContent='';let params=new URLSearchParams({q:$('#discoverQuery').value,provider:$('#provider').value,type:$('#contentType').value,duration:$('#duration').value,published:$('#published').value,order:$('#order').value});try{let r=await fetch('/api/search?'+params),d=await r.json();if(!r.ok)throw Error(d.error);let n=merge(d.results||[]);$('#warnings').textContent=(d.warnings||[]).join(' · ');render();toast(`${n} new results${d.cacheHit?' · cached':''}`)}catch(err){toast(err.message||'Search failed')}finally{b.disabled=false;b.textContent='Search'}};
async function showSettings(auto=false){let list=$('#healthList');list.innerHTML='<p class="muted">Checking…</p>';if(!$('#settingsDialog').open)$('#settingsDialog').showModal();try{let d=await (await fetch('/api/health')).json();list.innerHTML=Object.entries(d.providers).map(([name,v])=>`<div class="health-row"><b>${esc(name)}</b><span class="${v.ready?'ready':'setup'}">${v.ready?'Ready':'Needs setup'}</span></div>`).join('')+`<small class="muted">SQLite storage: ${d.storage.savedItems} saved items · persistent cache: ${d.cache.entries} entries / ${Math.round(d.cache.ttlSeconds/60)} minutes</small>`;if(auto&&!d.firstRun)$('#settingsDialog').close()}catch{list.innerHTML='<p class="setup">Health check unavailable</p>'}}
$('#settingsBtn').onclick=()=>showSettings();
$('#settingsForm').onsubmit=async e=>{e.preventDefault();let payload={YOUTUBE_API_KEY:$('#youtubeKey').value,VIMEO_ACCESS_TOKEN:$('#vimeoToken').value,DAILYMOTION_ACCESS_TOKEN:$('#dailymotionToken').value,PEERTUBE_INSTANCE:$('#peertubeInstance').value};try{let r=await fetch('/api/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!r.ok)throw Error();['#youtubeKey','#vimeoToken','#dailymotionToken'].forEach(s=>$(s).value='');toast('Provider setup saved');await showSettings()}catch{toast('Could not save provider setup')}};
$('#exportBtn').onclick=()=>{let data={app:'OpenMedia Lite',version:'3.0.0',exportedAt:new Date().toISOString(),libraries,subscriptions,playlists,reminders,bookmarks,items:items.filter(x=>x.source!=='Local file').map(({id,name,type,embed,sourceUrl,thumbnail,source,duration,publishedAt,favorite,library,description,watchLater,rating,notes,tags})=>({id,name,type,embed,sourceUrl,thumbnail,source,duration,publishedAt,favorite,library,description,watchLater,rating,notes,tags}))};let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='openmedia-library.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)};
$('#importBtn').onclick=()=>$('#importInput').click();$('#importInput').onchange=async e=>{try{let data=JSON.parse(await e.target.files[0].text());if(!Array.isArray(data.items))throw Error();pendingImport=data;let duplicateIds=data.items.filter(x=>items.some(i=>i.id===x.id)).length;$('#importPreviewContent').innerHTML=`<div><b>${data.items.length}</b><small>Media items</small></div><div><b>${duplicateIds}</b><small>Existing IDs skipped</small></div><div><b>${(data.libraries||[]).length}</b><small>Libraries</small></div><div><b>${(data.playlists||[]).length}</b><small>Playlists</small></div><div><b>${(data.subscriptions||[]).length}</b><small>Subscriptions</small></div><div><b>${(data.reminders||[]).length}</b><small>Reminders</small></div>`;$('#importPreviewDialog').showModal()}catch{toast('Invalid OpenMedia library file')}e.target.value=''};$('#confirmImportBtn').onclick=()=>{let data=pendingImport;if(!data)return;libraries=[...new Set([...libraries,...(data.libraries||[])])];subscriptions=[...subscriptions,...(data.subscriptions||[]).filter(s=>s?.url&&!subscriptions.some(x=>x.url===s.url))];playlists=[...playlists,...(data.playlists||[]).filter(p=>p?.name&&!playlists.some(x=>x.name===p.name))];reminders=[...reminders,...(data.reminders||[]).filter(r=>r?.due&&!reminders.some(x=>x.id===r.id))];bookmarks=[...bookmarks,...(data.bookmarks||[]).filter(b=>b?.itemId&&!bookmarks.some(x=>x.id===b.id))];localStorage.setItem('om_libraries',JSON.stringify(libraries));let n=merge(data.items);scheduleStateSave();render();pendingImport=null;$('#importPreviewDialog').close();toast(`${n} imported · duplicates skipped`)};


function playableQueue(){return playQueue.map(id=>items.find(x=>x.id===id)).filter(x=>x&&['video','audio','image'].includes(x.type))}
function moveQueue(direction){let q=playableQueue();if(!q.length)return;let at=q.findIndex(x=>x.id===current?.id);let target;if(shuffleOn&&q.length>1){let choices=q.filter(x=>x.id!==current?.id);target=choices[Math.floor(Math.random()*choices.length)]}else{let next=at+direction;if(next<0){if(repeatMode==='all')next=q.length-1;else return}if(next>=q.length){if(repeatMode==='all')next=0;else return}target=q[next]}if(target)play(target)}
function updateControlLabels(){$('#repeatBtn').textContent=repeatMode==='off'?'↻ Off':repeatMode==='all'?'↻ All':'↻ One';$('#repeatBtn').classList.toggle('active',repeatMode!=='off');$('#shuffleBtn').classList.toggle('active',shuffleOn)}
$('#prevBtn').onclick=()=>moveQueue(-1);$('#nextBtn').onclick=()=>moveQueue(1);$('#shuffleBtn').onclick=()=>{shuffleOn=!shuffleOn;updateControlLabels();scheduleStateSave()};$('#repeatBtn').onclick=()=>{repeatMode=repeatMode==='off'?'all':repeatMode==='all'?'one':'off';updateControlLabels();scheduleStateSave()};
$('#speedSelect').onchange=()=>{['video','audio'].forEach(id=>$('#'+id).playbackRate=Number($('#speedSelect').value));scheduleStateSave()};$('#muteBtn').onclick=()=>{let m=current&&!current.embed?$('#'+current.type):null;if(m&&['video','audio'].includes(current.type)){m.muted=!m.muted;$('#muteBtn').textContent=m.muted?'🔇':'🔊'}};$('#miniBtn').onclick=()=>document.body.classList.toggle('mini-player');
$('#queueAllBtn').onclick=()=>{playQueue=items.filter(x=>['video','audio','image'].includes(x.type)).map(x=>x.id);scheduleStateSave();renderQueue();toast('All playable items queued')};$('#shuffleAllBtn').onclick=()=>{playQueue=items.filter(x=>['video','audio','image'].includes(x.type)).map(x=>x.id).sort(()=>Math.random()-.5);shuffleOn=true;updateControlLabels();scheduleStateSave();renderQueue();toast('Queue shuffled')};

const providerSearch={youtube:q=>`https://www.youtube.com/results?search_query=${encodeURIComponent(q)}`,vimeo:q=>`https://vimeo.com/search?q=${encodeURIComponent(q)}`,dailymotion:q=>`https://www.dailymotion.com/search/${encodeURIComponent(q)}/videos`,peertube:q=>`https://sepiasearch.org/search?search=${encodeURIComponent(q)}`,soundcloud:q=>`https://soundcloud.com/search?q=${encodeURIComponent(q)}`,twitch:q=>`https://www.twitch.tv/search?term=${encodeURIComponent(q)}`,tiktok:q=>`https://www.tiktok.com/search?q=${encodeURIComponent(q)}`,reddit:q=>`https://www.reddit.com/search?q=${encodeURIComponent(q)}&type=link`,bilibili:q=>`https://search.bilibili.com/all?keyword=${encodeURIComponent(q)}`,rumble:q=>`https://rumble.com/search/?q=${encodeURIComponent(q)}`,odysee:q=>`https://odysee.com/search?q=${encodeURIComponent(q)}`,archive:q=>`https://archive.org/search?query=${encodeURIComponent(q)}`,ccc:q=>`https://media.ccc.de/search?q=${encodeURIComponent(q)}`,kick:q=>`https://kick.com/search?query=${encodeURIComponent(q)}`,niconico:q=>`https://search.nicovideo.jp/search/${encodeURIComponent(q)}?search_type=search`,x:q=>`https://x.com/search?q=${encodeURIComponent(q)}`,instagram:q=>`https://www.instagram.com/explore/tags/${encodeURIComponent(q)}/`};
let browserUrl='',browserHistory=[];
function looksLikeUrl(v){return /^(https?:\/\/)/i.test(v.trim())}
function browse(url){browserUrl=url;browserHistory.push(url);$('#browserAddress').textContent=url;$('#browserEmpty').hidden=true;$('#browserFrame').hidden=false;$('#browserFrame').src=url;$('#openExternal').disabled=false}
function portalGo(value,provider){let v=value.trim();if(!v)return;if(looksLikeUrl(v)){let media=parseWeb(v);if(media){if(!items.some(i=>i.id===media.id))items.unshift(media);scheduleStateSave();render();play(media);toast('Opened in the media player');return}browse(v);return}if(provider==='web')return toast('Enter a complete https:// website address');let maker=providerSearch[provider]||providerSearch.youtube;browse(maker(v))}
$('#portalForm').onsubmit=e=>{e.preventDefault();portalGo($('#portalQuery').value,$('#portalProvider').value)};
const FALLBACK_PROVIDERS=[{id:'youtube',name:'YouTube',keyless:true,capabilities:['search','embed']},{id:'vimeo',name:'Vimeo',keyless:false,capabilities:['search','embed']},{id:'dailymotion',name:'Dailymotion',keyless:true,capabilities:['search','embed']},{id:'peertube',name:'PeerTube',keyless:true,capabilities:['search','embed']},{id:'soundcloud',name:'SoundCloud',keyless:true,capabilities:['embed']},{id:'twitch',name:'Twitch',keyless:true,capabilities:['embed','live']},{id:'tiktok',name:'TikTok',keyless:true,capabilities:['embed']},{id:'reddit',name:'Reddit',keyless:true,capabilities:['embed']},{id:'bilibili',name:'Bilibili',keyless:true,capabilities:['embed']},{id:'rumble',name:'Rumble',keyless:true,capabilities:['embed']},{id:'odysee',name:'Odysee',keyless:true,capabilities:['search','embed']},{id:'archive',name:'Internet Archive',keyless:true,capabilities:['search','embed']},{id:'ccc',name:'media.ccc.de',keyless:true,capabilities:['search','embed']},{id:'kick',name:'Kick',keyless:true,capabilities:['embed','live']},{id:'niconico',name:'Niconico',keyless:true,capabilities:['embed']},{id:'x',name:'X (Twitter)',keyless:true,capabilities:['embed']},{id:'instagram',name:'Instagram',keyless:true,capabilities:['embed']}];
const providerMarks={youtube:'▶',vimeo:'V',dailymotion:'D',peertube:'P',soundcloud:'☁',twitch:'❘',tiktok:'♪',reddit:'r',bilibili:'B',rumble:'R',odysee:'O',archive:'A',ccc:'C',kick:'K',niconico:'N',x:'𝕏',instagram:'◎'};
function renderProviderStrip(list){const strip=$('#providerStrip');if(!strip)return;strip.innerHTML=list.map(p=>`<button data-provider="${esc(p.id)}" title="${esc(p.name)}${p.keyless?' · keyless':''}"><span class="provider-mark pm-${esc(p.id)}">${esc(providerMarks[p.id]||p.name[0])}</span><b>${esc(p.name)}</b><small>${p.keyless?'Keyless':'API key'}</small></button>`).join('');$$('#providerStrip button').forEach(b=>b.onclick=()=>{$('#portalProvider').value=b.dataset.provider;let q=$('#portalQuery').value.trim();if(q)portalGo(q,b.dataset.provider);else{$('#portalQuery').focus();toast(`Enter a ${b.querySelector('b').textContent} search`)}})}
async function loadProviderStrip(){try{let r=await fetch('/api/providers');if(!r.ok)throw 0;let d=await r.json();renderProviderStrip(d.providers||FALLBACK_PROVIDERS)}catch{renderProviderStrip(FALLBACK_PROVIDERS)}}
async function showConnect(){let list=$('#connectList');list.innerHTML='<p class="muted">Loading provider catalog…</p>';if(!$('#connectDialog').open)$('#connectDialog').showModal();try{let d=await(await fetch('/api/providers')).json();list.innerHTML=(d.providers||[]).map(p=>`<div class="connect-row"><div class="connect-mark pm-${esc(p.id)}">${esc(providerMarks[p.id]||p.name[0])}</div><div class="connect-meta"><b>${esc(p.name)} ${p.keyless?'<span class="badge keyless">Keyless</span>':'<span class="badge key">API key</span>'} ${p.ready?'<span class="badge ready">Ready</span>':(p.credentials?'<span class="badge setup">Needs key</span>':'')}</b><small>${esc(p.search||'')}</small><small class="connect-caps">${(p.capabilities||[]).map(c=>`<em>${esc(c)}</em>`).join('')}</small></div><div class="connect-actions">${p.signIn?`<button type="button" data-signin="${esc(p.signIn)}">Sign in ↗</button>`:''}${p.apiConsole?`<button type="button" data-console="${esc(p.apiConsole)}">Get API key ↗</button>`:''}${p.docs?`<button type="button" class="ghost" data-docs="${esc(p.docs)}">Docs ↗</button>`:''}</div></div>`).join('')}catch{list.innerHTML='<p class="setup">Provider catalog unavailable.</p>'}}
$('#connectBtn').onclick=showConnect;
document.addEventListener('click',e=>{let t=e.target.closest('[data-signin],[data-console],[data-docs]');if(!t)return;e.preventDefault();let url=t.dataset.signin||t.dataset.console||t.dataset.docs;if(t.dataset.signin){browse(url);$('#connectDialog').close()}else window.open(url,'_blank','noopener')});
loadProviderStrip();
$('#openExternal').onclick=()=>{if(browserUrl)window.open(browserUrl,'_blank','noopener')};
$('#browserHome').onclick=()=>{$('#browserFrame').src='about:blank';$('#browserFrame').hidden=true;$('#browserEmpty').hidden=false;$('#browserAddress').textContent='Choose a provider or enter an address';browserUrl='';$('#openExternal').disabled=true};
$('#browserBack').onclick=()=>{if(browserHistory.length>1){browserHistory.pop();browse(browserHistory.pop())}else $('#browserHome').click()};
function setMode(mode){let portal=mode==='portal';$('#portalPanel').hidden=!portal;$('#apiPanel').hidden=portal;$('#portalMode').classList.toggle('active',portal);$('#apiMode').classList.toggle('active',!portal)}
$('#portalMode').onclick=()=>setMode('portal');$('#apiMode').onclick=()=>setMode('api');






function formatTime(sec){sec=Math.max(0,Math.floor(Number(sec)||0));let h=Math.floor(sec/3600),m=Math.floor(sec%3600/60),s=sec%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${m}:${String(s).padStart(2,'0')}`}
function activeNativeMedia(){return current&&!current.embed&&['video','audio'].includes(current.type)?$('#'+current.type):null}
$('#bookmarkBtn').onclick=()=>{let m=activeNativeMedia();if(!current||!m)return toast('Timestamp bookmarks require native video or audio');$('#bookmarkMediaTitle').textContent=current.name;$('#bookmarkTimeLabel').textContent=formatTime(m.currentTime);$('#bookmarkDialog').dataset.itemId=current.id;$('#bookmarkDialog').dataset.position=String(m.currentTime);$('#bookmarkLabel').value='';$('#bookmarkNote').value='';$('#bookmarkDialog').showModal()};
$('#bookmarkForm').onsubmit=e=>{e.preventDefault();bookmarks.push({id:crypto.randomUUID(),itemId:$('#bookmarkDialog').dataset.itemId,position:Number($('#bookmarkDialog').dataset.position),label:$('#bookmarkLabel').value.trim(),note:$('#bookmarkNote').value.trim(),created:Date.now()});bookmarks.sort((a,b)=>b.created-a.created);scheduleStateSave();$('#bookmarkDialog').close();toast('Timestamp bookmark saved')};
function renderBookmarks(){let valid=bookmarks.map(b=>({...b,item:items.find(x=>x.id===b.itemId)})).filter(x=>x.item);$('#bookmarksList').innerHTML=valid.map(x=>`<div><button type="button" data-jump-bookmark="${esc(x.id)}"><span>${formatTime(x.position)}</span><div><b>${esc(x.label)}</b><small>${esc(x.item.name)}${x.note?' · '+esc(x.note):''}</small></div></button><button type="button" data-delete-bookmark="${esc(x.id)}">×</button></div>`).join('')||'<p class="muted">No timestamp bookmarks yet.</p>';$$('[data-jump-bookmark]').forEach(b=>b.onclick=()=>{let mark=bookmarks.find(x=>x.id===b.dataset.jumpBookmark),item=items.find(x=>x.id===mark?.itemId);if(item){play(item);let m=activeNativeMedia();if(m)m.onloadedmetadata=()=>{m.currentTime=mark.position;m.play().catch(()=>{})};$('#bookmarksListDialog').close()}});$$('[data-delete-bookmark]').forEach(b=>b.onclick=()=>{bookmarks=bookmarks.filter(x=>x.id!==b.dataset.deleteBookmark);scheduleStateSave();renderBookmarks()})}
$('#bookmarksListBtn').onclick=()=>{renderBookmarks();$('#bookmarksListDialog').showModal()};
function renderRecovery(){let item=items.find(x=>x.id===lastSession?.itemId);$('#recoveryCard').hidden=!item;if(item){$('#recoveryTitle').textContent=`${item.name}${lastSession.position?' · '+formatTime(lastSession.position):''}`}}
$('#recoveryBtn').onclick=()=>{let item=items.find(x=>x.id===lastSession?.itemId);if(!item)return;play(item);let m=activeNativeMedia();if(m&&lastSession.position)m.onloadedmetadata=()=>{m.currentTime=lastSession.position;m.play().catch(()=>{})}};
function applySessionModes(){document.body.classList.toggle('focus-mode',focusMode);document.body.classList.toggle('audio-mode',audioMode);$('#focusModeBtn').classList.toggle('active',focusMode);$('#audioModeBtn').classList.toggle('active',audioMode)}
$('#focusModeBtn').onclick=()=>{focusMode=!focusMode;applySessionModes()};$('#audioModeBtn').onclick=()=>{audioMode=!audioMode;applySessionModes()};

function renderPlaylists(){$('#playlistList').innerHTML=playlists.map((p,i)=>`<div class="subscription-item"><button data-playlist="${i}"><span>▤</span><div><b>${esc(p.name)}</b><small>${p.items.length} item${p.items.length!==1?'s':''}</small></div></button><button data-delete-playlist="${i}" title="Remove">×</button></div>`).join('')||'<small class="muted">Create playlists from selected media.</small>';$$('[data-playlist]').forEach(b=>b.onclick=()=>showPlaylist(Number(b.dataset.playlist)));$$('[data-delete-playlist]').forEach(b=>b.onclick=()=>{let i=Number(b.dataset.deletePlaylist);if(confirmDelete&&!confirm(`Delete playlist “${playlists[i].name}”?`))return;playlists.splice(i,1);scheduleStateSave();renderPlaylists()})}
$('#newPlaylist').onclick=()=>$('#playlistDialog').showModal();$('#playlistForm').onsubmit=e=>{e.preventDefault();let name=$('#playlistName').value.trim();if(!name)return;playlists.push({id:crypto.randomUUID(),name,items:[],created:Date.now()});scheduleStateSave();renderPlaylists();$('#playlistDialog').close();$('#playlistForm').reset();toast('Playlist created')};
function showPlaylist(i){activePlaylist=i;let p=playlists[i];$('#playlistItemsTitle').textContent=p.name;let list=p.items.map(id=>items.find(x=>x.id===id)).filter(Boolean);$('#playlistItemsList').innerHTML=list.map(x=>`<div><span>${typeIcon(x)}</span><div><b>${esc(x.name)}</b><small>${esc(x.source)}</small></div><button type="button" data-remove-playlist-item="${esc(x.id)}">×</button></div>`).join('')||'<p class="muted">This playlist is empty. Select media and use the Playlist batch action.</p>';$$('[data-remove-playlist-item]').forEach(b=>b.onclick=()=>{p.items=p.items.filter(id=>id!==b.dataset.removePlaylistItem);scheduleStateSave();showPlaylist(i);renderPlaylists()});$('#playlistItemsDialog').showModal()}
$('#playPlaylistBtn').onclick=()=>{if(activePlaylist===null)return;playQueue=playlists[activePlaylist].items.filter(id=>items.some(x=>x.id===id));renderQueue();scheduleStateSave();let first=items.find(x=>x.id===playQueue[0]);if(first)play(first);$('#playlistItemsDialog').close()};
$('#shareBtn').onclick=async()=>{if(!current?.sourceUrl)return toast('This item has no shareable source link');let data={title:current.name,text:`${current.name} — ${current.source}`,url:current.sourceUrl};try{if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(current.sourceUrl);toast('Source link copied')}}catch(e){if(e.name!=='AbortError')toast('Sharing is unavailable')}};
$('#remindBtn').onclick=()=>{if('Notification'in window&&Notification.permission==='default')Notification.requestPermission();if(!current)return;$('#reminderTitle').textContent=current.name;let dt=new Date(Date.now()+3600000);dt.setMinutes(dt.getMinutes()-dt.getTimezoneOffset());$('#reminderTime').value=dt.toISOString().slice(0,16);$('#reminderNote').value='';$('#reminderDialog').showModal()};$('#reminderForm').onsubmit=e=>{e.preventDefault();if(!current)return;let due=new Date($('#reminderTime').value).getTime();if(!due||due<=Date.now())return toast('Choose a future time');reminders.push({id:crypto.randomUUID(),itemId:current.id,title:current.name,due,note:$('#reminderNote').value.trim(),notified:false});reminders.sort((a,b)=>a.due-b.due);scheduleStateSave();$('#reminderDialog').close();toast('Reminder saved')};
function renderReminders(){$('#reminderList').innerHTML=reminders.map((r,i)=>`<div><div><b>${esc(r.title)}</b><small>${new Date(r.due).toLocaleString()}${r.note?' · '+esc(r.note):''}</small></div><button type="button" data-remove-reminder="${i}">×</button></div>`).join('')||'<p class="muted">No watch reminders.</p>';$$('[data-remove-reminder]').forEach(b=>b.onclick=()=>{reminders.splice(Number(b.dataset.removeReminder),1);scheduleStateSave();renderReminders()})}
$('#remindersBtn').onclick=()=>{if('Notification'in window&&Notification.permission==='default')Notification.requestPermission();renderReminders();$('#remindersDialog').showModal()};
async function checkReminders(){let due=reminders.filter(r=>!r.notified&&r.due<=Date.now());for(let r of due){r.notified=true;toast(`Reminder: ${r.title}`);if('Notification'in window&&Notification.permission==='granted')new Notification('OpenMedia reminder',{body:r.note||r.title})}if(due.length)scheduleStateSave()}
setInterval(checkReminders,30000);setTimeout(checkReminders,1200);

function renderSubscriptions(){$('#subscriptionList').innerHTML=subscriptions.map((s,i)=>`<div class="subscription-item"><button data-subscription="${i}"><span>${esc((s.provider||'Web').slice(0,1))}</span><div><b>${esc(s.name)}</b><small>${esc(s.provider||'Web')}</small></div></button><button data-unsubscribe="${i}" title="Remove">×</button></div>`).join('')||'<small class="muted">Save creator or channel pages here.</small>';$$('[data-subscription]').forEach(b=>b.onclick=()=>{let s=subscriptions[Number(b.dataset.subscription)];setMode('portal');$('#portalProvider').value='web';$('#portalQuery').value=s.url;portalGo(s.url,'web');window.scrollTo({top:0,behavior:'smooth'})});$$('[data-unsubscribe]').forEach(b=>b.onclick=()=>{let i=Number(b.dataset.unsubscribe);if(confirmDelete&&!confirm(`Remove subscription “${subscriptions[i].name}”?`))return;subscriptions.splice(i,1);scheduleStateSave();renderSubscriptions()})}
$('#newSubscription').onclick=()=>{$('#subscriptionDialog').showModal();setTimeout(()=>$('#subscriptionName').focus(),30)};$('#subscriptionForm').onsubmit=e=>{e.preventDefault();let entry={id:crypto.randomUUID(),name:$('#subscriptionName').value.trim(),provider:$('#subscriptionProvider').value,url:$('#subscriptionUrl').value.trim(),added:Date.now()};if(!entry.name||!entry.url)return;subscriptions.unshift(entry);scheduleStateSave();renderSubscriptions();$('#subscriptionDialog').close();$('#subscriptionForm').reset();toast('Subscription saved')};
$('#watchLaterBtn').onclick=()=>{if(!current)return;current.watchLater=!current.watchLater;scheduleStateSave();render();updateNowBar(current);toast(current.watchLater?'Added to Watch Later':'Removed from Watch Later')};
function paintRating(){$$('#ratingRow [data-rating]').forEach(b=>b.classList.toggle('active',Number(b.dataset.rating)<=detailRating))}
$('#detailsBtn').onclick=()=>{if(!current)return;detailRating=current.rating||0;$('#detailsTitle').textContent=current.name;$('#itemNotes').value=current.notes||'';$('#itemTags').value=(current.tags||[]).join(', ');paintRating();$('#detailsDialog').showModal()};$$('#ratingRow [data-rating]').forEach(b=>b.onclick=()=>{detailRating=Number(b.dataset.rating);paintRating()});$('#detailsForm').onsubmit=e=>{e.preventDefault();if(!current)return;current.rating=detailRating;current.notes=$('#itemNotes').value.trim();current.tags=$('#itemTags').value.split(',').map(x=>x.trim()).filter(Boolean).slice(0,12);scheduleStateSave();render();updateNowBar(current);$('#detailsDialog').close();toast('Rating and notes saved')};$('#clearDetailsBtn').onclick=()=>{detailRating=0;$('#itemNotes').value='';$('#itemTags').value='';paintRating()};
function insights(){let played=history.map(h=>items.find(x=>x.id===h.id)).filter(Boolean),providers={};played.forEach(x=>providers[x.source]=(providers[x.source]||0)+1);let top=Object.entries(providers).sort((a,b)=>b[1]-a[1]).slice(0,5);let rated=items.filter(x=>x.rating>0),avg=rated.length?rated.reduce((n,x)=>n+x.rating,0)/rated.length:0;let resumed=Object.values(progress).filter(x=>x.position>5).length;let week=history.filter(h=>Date.now()-h.playedAt<604800000).length;return {played:history.length,week,watchLater:items.filter(x=>x.watchLater).length,rated:rated.length,average:avg,resumed,subscriptions:subscriptions.length,top}}
$('#insightsBtn').onclick=()=>{let d=insights();$('#insightsContent').innerHTML=`<div class="insight-cards"><div><b>${d.played}</b><small>Total plays</small></div><div><b>${d.week}</b><small>Last 7 days</small></div><div><b>${d.watchLater}</b><small>Watch Later</small></div><div><b>${d.average?d.average.toFixed(1):'—'}</b><small>Average rating</small></div><div><b>${d.resumed}</b><small>Progress records</small></div><div><b>${d.subscriptions}</b><small>Subscriptions</small></div></div><h3>Most played providers</h3><div class="provider-insights">${d.top.map(([name,count],i)=>`<div><span>${i+1}. ${esc(name)}</span><b>${count}</b></div>`).join('')||'<p class="muted">Play saved media to build insights.</p>'}</div>`;$('#insightsDialog').showModal()};

function toggleSelection(id){selected.has(id)?selected.delete(id):selected.add(id);render()}
function updateBatchBar(){$('#batchBar').hidden=!selectMode;$('#selectedCount').textContent=`${selected.size} selected`}
function setSelectMode(on){selectMode=on;if(!on)selected.clear();$('#selectModeBtn').classList.toggle('active',on);render()}
$('#selectModeBtn').onclick=()=>setSelectMode(!selectMode);$('#cancelSelectBtn').onclick=()=>setSelectMode(false);$('#selectAllBtn').onclick=()=>{filtered().forEach(x=>selected.add(x.id));render()};
$('#batchFavoriteBtn').onclick=()=>{items.filter(x=>selected.has(x.id)).forEach(x=>x.favorite=true);scheduleStateSave();setSelectMode(false);toast('Selected items favorited')};
$('#batchQueueBtn').onclick=()=>{items.filter(x=>selected.has(x.id)&&['video','audio','image'].includes(x.type)).forEach(x=>{if(!playQueue.includes(x.id))playQueue.push(x.id)});scheduleStateSave();setSelectMode(false);renderQueue();toast('Selected items queued')};
$('#batchPlaylistBtn').onclick=async()=>{if(!playlists.length)return toast('Create a playlist first');let name=await pickOption('Add selected to playlist',playlists.map(p=>p.name));if(!name)return;let p=playlists.find(x=>x.name===name);if(p){items.filter(x=>selected.has(x.id)).forEach(x=>{if(!p.items.includes(x.id))p.items.push(x.id)});scheduleStateSave();setSelectMode(false);renderPlaylists();toast(`Added to ${p.name}`)}};
$('#batchLibraryBtn').onclick=async()=>{if(!libraries.length)return toast('Create a library first');let name=await pickOption('Add selected to library',libraries);if(!name)return;items.filter(x=>selected.has(x.id)).forEach(x=>x.library=name);scheduleStateSave();setSelectMode(false);render();toast(`Added to ${name}`)};
$('#batchRemoveBtn').onclick=()=>{if(!selected.size)return;let count=selected.size;if(confirmDelete&&!confirm(`Delete ${count} selected saved item${count!==1?'s':''}?`))return;items=items.filter(x=>!selected.has(x.id));playQueue=playQueue.filter(id=>!selected.has(id));history=history.filter(h=>!selected.has(h.id));selected.clear();scheduleStateSave();setSelectMode(false);toast(`${count} item${count!==1?'s':''} deleted`)};
function duplicateGroups(){let groups=new Map();items.filter(x=>x.source!=='Local file').forEach(x=>{let key=(x.sourceUrl||x.embed||'').replace(/[?&](autoplay|auto_play)=1/g,'').toLowerCase();if(!key)return;groups.set(key,[...(groups.get(key)||[]),x])});return [...groups.values()].filter(g=>g.length>1)}
function incompleteItems(){return items.filter(x=>x.source!=='Local file'&&!x.url&&!x.embed&&!x.sourceUrl)}
function showMaintenance(){let dupes=duplicateGroups(),broken=incompleteItems();$('#maintenanceStats').innerHTML=`<div><b>${items.filter(x=>x.source!=='Local file').length}</b><small>Saved web items</small></div><div><b>${dupes.reduce((n,g)=>n+g.length-1,0)}</b><small>Duplicate copies</small></div><div><b>${broken.length}</b><small>Incomplete items</small></div><div><b>${history.length}</b><small>History records</small></div>`;if(!$('#maintenanceDialog').open)$('#maintenanceDialog').showModal()}
$('#maintenanceBtn').onclick=showMaintenance;$('#dedupeBtn').onclick=()=>{let groups=duplicateGroups(),remove=new Set();groups.forEach(g=>g.slice(1).forEach(x=>remove.add(x.id)));if(!remove.size)return toast('No duplicate URLs found');if(confirmDelete&&!confirm(`Remove ${remove.size} duplicate item${remove.size!==1?'s':''}?`))return;items=items.filter(x=>!remove.has(x.id));playQueue=playQueue.filter(id=>!remove.has(id));scheduleStateSave();render();showMaintenance();toast('Duplicate URLs merged')};
$('#removeBrokenBtn').onclick=()=>{let broken=incompleteItems(),ids=new Set(broken.map(x=>x.id));if(!ids.size)return toast('No incomplete items found');if(confirmDelete&&!confirm(`Remove ${ids.size} incomplete item${ids.size!==1?'s':''}?`))return;items=items.filter(x=>!ids.has(x.id));scheduleStateSave();render();showMaintenance();toast('Incomplete items removed')};
async function maintenance(action,message){if(!confirm(message))return;try{let r=await fetch('/api/maintenance',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})});if(!r.ok)throw Error();if(action==='clear-history')history=[];if(action==='clear-progress')progress={};render();showMaintenance();toast('Maintenance completed')}catch{toast('Maintenance failed')}}
$('#clearHistoryBtn').onclick=()=>maintenance('clear-history','Clear all playback history?');$('#clearProgressBtn').onclick=()=>maintenance('clear-progress','Clear all saved playback positions?');$('#clearCacheBtn').onclick=()=>maintenance('clear-cache','Clear the persistent API response cache?');
function applyPreferences(){let light=appearance==='light'||(appearance==='system'&&matchMedia('(prefers-color-scheme: light)').matches);document.body.classList.toggle('light',light);document.body.classList.toggle('compact-library',density==='compact');document.body.classList.toggle('reduced-motion',reducedMotion);document.body.classList.toggle('high-contrast',highContrast);document.body.classList.toggle('large-text',largeText)}
$('#preferencesBtn').onclick=()=>{$('#appearancePref').value=appearance;$('#densityPref').value=density;$('#autoAdvancePref').checked=autoAdvance;$('#confirmDeletePref').checked=confirmDelete;$('#reducedMotionPref').checked=reducedMotion;$('#highContrastPref').checked=highContrast;$('#largeTextPref').checked=largeText;$('#preferencesDialog').showModal()};
$('#preferencesForm').onsubmit=e=>{e.preventDefault();appearance=$('#appearancePref').value;density=$('#densityPref').value;autoAdvance=$('#autoAdvancePref').checked;confirmDelete=$('#confirmDeletePref').checked;reducedMotion=$('#reducedMotionPref').checked;highContrast=$('#highContrastPref').checked;largeText=$('#largeTextPref').checked;applyPreferences();scheduleStateSave();$('#preferencesDialog').close();toast('Preferences saved')};


function pickOption(title, options){return new Promise(resolve=>{let d=$('#pickerDialog');$('#pickerTitle').textContent=title;$('#pickerList').innerHTML=options.map((o,i)=>`<button type="button" data-i="${i}">${esc(o)}</button>`).join('');$$('#pickerList button').forEach(b=>b.onclick=()=>{d.close();resolve(options[Number(b.dataset.i)])});d.addEventListener('close',()=>resolve(null),{once:true});d.showModal()})}
const welcomeDismissed=localStorage.getItem('om_welcome')==='dismissed';if(welcomeDismissed&&$('#welcomeHint'))$('#welcomeHint').remove();$('#dismissWelcome')?.addEventListener('click',()=>{$('#welcomeHint')?.remove();localStorage.setItem('om_welcome','dismissed')});
const commandActions=[
 {name:'Open Browser Hub',hint:'Navigation',run:()=>{setMode('portal');window.scrollTo({top:0,behavior:'smooth'})}},
 {name:'Open API Discovery',hint:'Navigation',run:()=>{setMode('api');window.scrollTo({top:0,behavior:'smooth'})}},
 {name:'Add local media',hint:'Action',run:()=>$('#fileInput').click()},
 {name:'Open media URL',hint:'Action',run:()=>$('#urlDialog').showModal()},
 {name:'Queue all playable items',hint:'Queue',run:()=>$('#queueAllBtn').click()},
 {name:'Shuffle the queue',hint:'Queue',run:()=>$('#shuffleAllBtn').click()},
 {name:'Show favorites',hint:'View',run:()=>openView('favorite','Favorites')},{name:'Show Watch Later',hint:'View',run:()=>openView('watchlater','Watch later')},{name:'Show rated media',hint:'View',run:()=>openView('rated','Rated')},{name:'Open usage insights',hint:'Library',run:()=>$('#insightsBtn').click()},
 {name:'Show Continue Watching',hint:'View',run:()=>openView('continue','Continue watching')},
 {name:'Show playback history',hint:'View',run:()=>openView('history','History')},
 {name:'Create full backup',hint:'Data',run:()=>$('#backupBtn').click()},
 {name:'Open diagnostics',hint:'Support',run:()=>$('#diagnosticsBtn').click()}
];
let commandSelection=0,commandMatches=[];
function openView(name,title){view=name;$('#viewTitle').textContent=title;render();$('#commandDialog').close()}
function renderCommands(){let q=$('#commandInput').value.toLowerCase().trim();let media=items.filter(x=>x.name.toLowerCase().includes(q)).slice(0,8).map(x=>({name:x.name,hint:x.source,run:()=>{play(x);$('#commandDialog').close()}}));let actions=commandActions.filter(x=>!q||x.name.toLowerCase().includes(q)||x.hint.toLowerCase().includes(q));commandMatches=[...actions,...media].slice(0,12);commandSelection=Math.min(commandSelection,Math.max(0,commandMatches.length-1));$('#commandResults').innerHTML=commandMatches.map((x,i)=>`<button type="button" class="command-result ${i===commandSelection?'selected':''}" data-command="${i}"><span>${esc(x.name)}</span><small>${esc(x.hint)}</small></button>`).join('')||'<p class="muted">No matching media or command.</p>';$$('[data-command]').forEach(b=>b.onclick=()=>commandMatches[Number(b.dataset.command)].run())}
function showCommands(){commandSelection=0;$('#commandInput').value='';$('#commandDialog').showModal();renderCommands();setTimeout(()=>$('#commandInput').focus(),30)}
$('#commandBtn').onclick=showCommands;$('#commandInput').oninput=()=>{commandSelection=0;renderCommands()};$('#commandInput').onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();commandSelection=Math.min(commandSelection+1,commandMatches.length-1);renderCommands()}if(e.key==='ArrowUp'){e.preventDefault();commandSelection=Math.max(commandSelection-1,0);renderCommands()}if(e.key==='Enter'&&commandMatches[commandSelection]){e.preventDefault();commandMatches[commandSelection].run()}};
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showCommands()}});
$('#backupBtn').onclick=async()=>{try{let data=await(await fetch('/api/backup')).json();let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=`openmedia-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500);toast('Full backup created')}catch{toast('Backup failed')}};
$('#restoreBtn').onclick=()=>$('#restoreInput').click();$('#restoreInput').onchange=async e=>{try{let data=JSON.parse(await e.target.files[0].text());if(!confirm('Replace saved libraries, queue, history, and progress with this backup?'))return;let r=await fetch('/api/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!r.ok)throw Error();location.reload()}catch{toast('Backup restore failed')}finally{e.target.value=''}};
let diagnosticsText='';$('#diagnosticsBtn').onclick=async()=>{$('#diagnosticsContent').innerHTML='<p class="muted">Checking…</p>';$('#diagnosticsDialog').showModal();try{let d=await(await fetch('/api/diagnostics')).json();diagnosticsText=`OpenMedia ${d.version}\nUptime: ${d.uptimeSeconds}s\nDatabase: ${d.databaseBytes} bytes\nItems: ${d.tables.items}\nLibraries: ${d.tables.libraries}\nProgress: ${d.tables.progress}\nCache: ${d.tables.cache}\nVault: ${d.vaultConfigured?'configured':'not configured'}\nBinding: ${d.host}:${d.port}`;$('#diagnosticsContent').innerHTML=Object.entries({Version:d.version,'Server uptime':`${d.uptimeSeconds} seconds`,'Database size':`${d.databaseBytes} bytes`,'Saved items':d.tables.items,Libraries:d.tables.libraries,'Progress records':d.tables.progress,'Cache entries':d.tables.cache,'Credential vault':d.vaultConfigured?'Configured':'Not configured','Local binding':`${d.host}:${d.port}`}).map(([k,v])=>`<div><small>${esc(k)}</small><b>${esc(v)}</b></div>`).join('')}catch{$('#diagnosticsContent').innerHTML='<p class="setup">Diagnostics unavailable.</p>'}};$('#copyDiagnosticsBtn').onclick=()=>navigator.clipboard?.writeText(diagnosticsText).then(()=>toast('Diagnostics copied')).catch(()=>toast('Copy unavailable'));

$('#fileInput').onchange=e=>addFiles(e.target.files);$('#folderInput').onchange=e=>addFiles(e.target.files);$('#addFiles').onclick=$('#emptyAdd').onclick=()=>$('#fileInput').click();$('#addFolder').onclick=()=>$('#folderInput').click();$('#addUrl').onclick=$('#emptyUrl').onclick=()=>$('#urlDialog').showModal();$('#openUrlBtn').onclick=e=>{e.preventDefault();if($('#urlInput').value)addUrl($('#urlInput').value);$('#urlDialog').close()};$('#newLibrary').onclick=()=>$('#libraryDialog').showModal();$('#createLibraryBtn').onclick=e=>{e.preventDefault();let n=$('#libraryName').value.trim();if(n&&!libraries.includes(n)){libraries.push(n);localStorage.setItem('om_libraries',JSON.stringify(libraries));scheduleStateSave();renderLibraries()}$('#libraryDialog').close()};
$$('.nav').forEach(b=>b.onclick=()=>{$$('.nav').forEach(x=>x.classList.remove('active'));b.classList.add('active');view=b.dataset.view;$('#viewTitle').textContent=b.textContent.replace(/\d+$/,'').trim();render()});$('#search').oninput=render;const sortCycle=[['recent','↕ Recently added'],['oldest','↕ Oldest first'],['rating','★ Top rated'],['az','A–Z']];let sortIdx=0;$('#sortBtn').onclick=()=>{sortIdx=(sortIdx+1)%sortCycle.length;sortMode=sortCycle[sortIdx][0];$('#sortBtn').textContent=sortCycle[sortIdx][1];render()};$('#gridView').onclick=()=>$('#mediaGrid').classList.remove('list');$('#listView').onclick=()=>$('#mediaGrid').classList.add('list');$('#addToLibraryBtn').onclick=async()=>{if(!current)return;if(!libraries.length)return toast('Create a library first');let n=await pickOption('Add to library',libraries);if(!n)return;current.library=n;scheduleStateSave();render();toast(`Added to ${n}`)};$('#favBtn').onclick=()=>{if(current){current.favorite=!current.favorite;scheduleStateSave();render();updateNowBar(current);toast(current.favorite?'Added to favorites':'Removed from favorites')}};$('#fullscreenBtn').onclick=()=>$('#dropZone').requestFullscreen?.();$('#themeBtn').onclick=()=>{appearance=document.body.classList.contains('light')?'dark':'light';applyPreferences();scheduleStateSave()};$('#clearQueue').onclick=()=>{playQueue=[];scheduleStateSave();renderQueue();toast('Queue cleared')};
let dz=$('#dropZone');['dragenter','dragover'].forEach(n=>dz.addEventListener(n,e=>{e.preventDefault();dz.classList.add('drag')}));['dragleave','drop'].forEach(n=>dz.addEventListener(n,e=>{e.preventDefault();dz.classList.remove('drag')}));dz.addEventListener('drop',e=>addFiles(e.dataTransfer.files));document.addEventListener('paste',e=>{let t=e.clipboardData.getData('text');if(/^https?:\/\//.test(t))addUrl(t)});document.addEventListener('keydown',e=>{if(['INPUT','SELECT','DIALOG'].includes(document.activeElement.tagName))return;let m=current&&!current.embed?$('#'+current.type):null;if(e.code==='Space'&&m&&current.type!=='image'){e.preventDefault();m.paused?m.play():m.pause()}if(m&&['video','audio'].includes(current?.type)){if(e.key==='ArrowRight')m.currentTime+=5;if(e.key==='ArrowLeft')m.currentTime-=5}let k=e.key.toLowerCase();if(k==='f')$('#dropZone').requestFullscreen?.();if(k==='s'&&!e.ctrlKey&&!e.metaKey){e.preventDefault();surpriseMe()}if(k==='m'&&!e.ctrlKey&&!e.metaKey)$('#muteBtn').click();if(k==='b'&&!e.ctrlKey&&!e.metaKey)$('#bookmarkBtn').click();if(k==='w'&&!e.ctrlKey&&!e.metaKey)$('#watchLaterBtn').click()});['video','audio'].forEach(id=>{let m=$('#'+id);m.addEventListener('volumechange',()=>{volumeLevel=m.volume;scheduleStateSave()});m.addEventListener('timeupdate',()=>{if(!current||!isFinite(m.duration)||Date.now()-lastProgressSave<5000)return;lastProgressSave=Date.now();progress[current.id]={position:m.currentTime,duration:m.duration,updated:Date.now()/1000};lastSession={itemId:current.id,position:m.currentTime,duration:m.duration,playedAt:Date.now()};fetch('/api/progress',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:current.id,position:m.currentTime,duration:m.duration})}).catch(()=>{});if(view==='continue')render()});m.addEventListener('ended',()=>{if(current)progress[current.id]={position:0,duration:m.duration,updated:Date.now()/1000};if(repeatMode==='one'){m.currentTime=0;m.play().catch(()=>{})}else if(autoAdvance)moveQueue(1)})});window.addEventListener('beforeunload',()=>{objectUrls.forEach(URL.revokeObjectURL);try{let webItems=items.filter(x=>x.source!=='Local file');if(!webItems.length&&!libraries.length)return;let body=JSON.stringify({libraries,items:webItems,queue:playQueue.filter(id=>webItems.some(x=>x.id===id)),history:history.slice(0,100),preferences:{repeatMode,shuffleOn,appearance,density,autoAdvance,confirmDelete,reducedMotion,highContrast,largeText,subscriptions,playlists,reminders,bookmarks,lastSession,volume:volumeLevel,speed:Number($('#speedSelect').value||1)},replaceItems:true,replaceLibraries:true});navigator.sendBeacon('/api/state',new Blob([body],{type:'application/json'}))}catch{}});if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js');loadState();

// === ✨ Next interesting video — local recommendation engine ===
let recoJitter=0;
function recoSeeds(){return history.slice(0,5).map(h=>items.find(x=>x.id===h.id)).filter(Boolean)}
function scoreReco(x,seeds){let s=Math.random()*(recoJitter?4:0.5),reasons=[];if(x.rating>0){s+=x.rating*1.5;reasons.push('★'+x.rating)}if(x.favorite){s+=2;reasons.push('favorite')}let sharedSrc=0;const tagHits=new Map();for(const seed of seeds){for(const t of (x.tags||[]))if((seed.tags||[]).includes(t))tagHits.set(t,(tagHits.get(t)||0)+1);if(x.source===seed.source)sharedSrc++;if(seed.library&&seed.library===x.library)s+=1.5}if(tagHits.size){let best=[...tagHits.entries()].sort((a,b)=>b[1]-a[1])[0];s+=4*best[1];reasons.unshift('#'+best[0])}if(sharedSrc){s+=1.5*sharedSrc;reasons.push(x.source)}const p=progress[x.id];if(p&&p.position>5&&p.duration-p.position>10){s+=8;reasons.unshift('resume')}if(history.some(h=>h.id===x.id))s-=9;return {score:s,reasons:[...new Set(reasons)].slice(0,2)}}
function computeReco(limit=6){const seeds=recoSeeds();const seen=new Set(history.slice(0,50).map(h=>h.id));const pool=items.filter(x=>['video','audio'].includes(x.type)&&x.id!==current?.id&&!seen.has(x.id));const scored=pool.map(x=>({x,...scoreReco(x,seeds)})).sort((a,b)=>b.score-a.score);return {seeds,picks:scored.slice(0,limit)}}
function renderReco(){const rail=$('#recoRail');if(!rail)return;const {seeds,picks}=computeReco(6);const playable=picks.filter(p=>p.score>-2);if(playable.length<3){rail.hidden=true;return}rail.hidden=false;$('#recoTitle').textContent=seeds.length?`Because you watched “${seeds[0].name.slice(0,60)}${seeds[0].name.length>60?'…':''}”`:'Top picks for you';$('#recoRow').innerHTML=playable.map(({x,reasons})=>`<button class="reco-card" data-reco="${esc(x.id)}"><span class="reco-thumb">${x.thumbnail?`<img src="${esc(x.thumbnail)}" alt="" loading="lazy">`:`<span class="type-icon">${typeIcon(x)}</span>`}</span><b title="${esc(x.name)}">${esc(x.name)}</b><small>${reasons.map(r=>`<em>${esc(r)}</em>`).join(' ')}</small></button>`).join('');$$('#recoRow [data-reco]').forEach(b=>b.onclick=()=>{const item=items.find(i=>i.id===b.dataset.reco);if(item)play(item)})}
function surpriseMe(){const {picks}=computeReco(12);const candidates=picks.filter(p=>p.score>-2);if(!candidates.length)return toast('Not enough media yet — add videos or watch a few first');const total=candidates.reduce((n,p)=>n+Math.max(0.1,p.score+3),0);let r=Math.random()*total;for(const p of candidates){r-=Math.max(0.1,p.score+3);if(r<=0)return play(p.x)}play(candidates[candidates.length-1].x)}
$('#surpriseBtn').onclick=surpriseMe;$('#recoRefresh').onclick=()=>{recoJitter++;renderReco()};
commandActions.push({name:'Play something interesting',hint:'Reco',run:surpriseMe},{name:'Refresh recommendation picks',hint:'Reco',run:()=>{recoJitter++;renderReco();toast('Picks reshuffled')}});
const _origRender=render;render=function(){_origRender();renderReco()};

